// =================================================================== r6 HEMOMANCER — ported from the user's own Midjourney animations
// Source: refs/hemo_mj2/gifs #6 #7 #8 (the white-robed penitent turning and walking). Every frame is a frame of those
// videos: the black ground and the floor strip cut away, all frames scaled by one factor (no size breathing), one shared
// 48-colour palette (no colour flicker), a dark outline, feet anchored. Built by scratchpad/hemo_port/build_r6.py.
// Replaces r5 (hand-built rects, drawn 3x too large). Views: side, front (3/4), down, back (3/4), up; the walk is his own
// stride from video #7. Hero pixel = 2 screen px, like the Ossuarch (hr twin at 1.5x world).
{
  const R6 = {"sheets": {"side": "data:image/png;base64,", "front": "data:image/png;base64,", "down": "data:image/png;base64,", "back": "data:image/png;base64,", "up": "data:image/png;base64,", "walk": "data:image/png;base64,"}, "n": {"side": 8, "front": 8, "down": 10, "back": 8, "up": 10, "walk": 11}, "FW": 84, "FH": 90, "AX": 42, "AY": 84};
  const R6_K = 1.5, R6_W = R6.FW / R6_K, R6_H = R6.FH / R6_K, R6_OX = R6.AX / R6_K, R6_OY = R6.AY / R6_K;
  const R6_FR = {}; let R6_ok = false, R6_left = 0;
  const lo = src => { const q = mkCanvas(R6_W, R6_H), x = q.getContext('2d'); x.imageSmoothingEnabled = false; x.drawImage(src, 0, 0, R6_W, R6_H); q._hr = src; return q; };
  const flip = src => { const q = mkCanvas(src.width, src.height), x = q.getContext('2d'); x.translate(src.width, 0); x.scale(-1, 1); x.drawImage(src, 0, 0); return q; };
  const tintH = (src, col) => { const q = mkCanvas(src.width, src.height), x = q.getContext('2d'); x.drawImage(src, 0, 0); x.globalCompositeOperation = 'source-in'; x.fillStyle = col; x.fillRect(0, 0, q.width, q.height); return q; };
  const shift = (src, dy) => { const q = mkCanvas(src.width, src.height), x = q.getContext('2d'); x.drawImage(src, 0, dy); return q; };
  function frameOf(hr) {
    const hf = flip(hr);
    return { c: lo(hr), f: lo(hf), fl: lo(tintH(hr, '#fff')), flf: lo(tintH(hf, '#fff')), w: R6_W, h: R6_H, ox: R6_OX, oy: R6_OY,
      bb: { x: R6_OX - 11, y: R6_OY - 50, w: 22, h: 50 }, tint: (src, col) => lo(tintH(src._hr || src, col)), hd: true };
  }
  for (const v in R6.sheets) {
    R6_left++;
    const img = new Image();
    img.onload = () => {
      const n = R6.n[v], out = [];
      for (let i = 0; i < n; i++) { const c = mkCanvas(R6.FW, R6.FH), x = c.getContext('2d'); x.drawImage(img, -i * R6.FW, 0); out.push(c); }
      R6_FR[v] = out.map(frameOf);
      // straight toward or away from the camera there is no stride in the videos: those walk with a step's rise and fall
      if (v === 'down' || v === 'up') R6_FR[v + '_walk'] = [0, 1, 0, -1].map((dy, k) => frameOf(shift(out[(k * 2) % n], -Math.abs(dy))));
      if (--R6_left === 0) R6_ok = true;
    };
    img.src = R6.sheets[v];
  }
  // idles ping-pong through their frames (the videos do not loop), so nothing pops
  const pingpong = (t, n) => { const m = Math.max(1, 2 * n - 2), k = ((t % m) + m) % m; return k < n ? k : m - k; };
  const VIEWS = { side: 1, front: 1, down: 1, back: 1, up: 1 };
  const _prevHF = heroFrame;
  heroFrame = function (cls, pose, ph, view) {
    if (cls !== 'hemomancer' || !R6_ok) return _prevHF(cls, pose, ph, view);
    let v = view || P._view || 'front'; if (!VIEWS[v]) v = 'front';
    if (pose === 'walk') {
      if (v === 'down' || v === 'up') { const L = R6_FR[v + '_walk']; return L[((ph | 0) % L.length + L.length) % L.length]; }
      const L = R6_FR.walk; return L[((ph | 0) % L.length + L.length) % L.length];
    }
    const L = R6_FR[v] || R6_FR.front;
    return L[pingpong(ph | 0, L.length)];
  };
  const _prevHP = heroPose;
  heroPose = function () {
    const r = _prevHP();
    if (typeof P !== 'undefined' && P && P.cls === 'hemomancer' && R6_ok) {
      if (r[0] === 'walk') return ['walk', Math.floor(((P._wd || 0) * 5.2 + G.time * 2) % 11)];
      return ['idle', Math.floor(G.time * 6)];
    }
    return r;
  };
  try { window.__r6Hemo = { R6_FR, get ok() { return R6_ok; } }; } catch (e) { }
}
